/** Англійські індекси для символів у HTML-рядках (українські — за замовчуванням). */
const SUB_EN: [string, string][] = [
  ['вих', 'out'], ['вх', 'in'], ['пов', 'full'], ['тіло', 'body'], ['лоп,max', 'scap,max'], ['пл,max', 'GH,max'], ['об', 'housing'],
  ['ТП', 'TD'], ['зг', 'flex'], ['сп', 'back'], ['бл', 'lock'], ['пп', 'fa'], ['гак', 'hook'],
];
export function sym(lang: Lang, html: string): string {
  if (lang === 'uk') return html;
  return html.replace(/<sub>([^<]+)<\/sub>/g, (_m, t: string) => `<sub>${SUB_EN.find(([u]) => u === t)?.[1] ?? t}</sub>`);
}

